#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, M, etc.)
#include "correlation.hpp"

using num_t = DATA_TYPE;

using namespace Halide;


/**
 * Initialize the input array `data` and the scalar `float_n`.
 * This mirrors the PolyBench init_array() logic:
 *
 *   *float_n = (DATA_TYPE)N;
 *   data[i][j] = (DATA_TYPE)(i*j)/M + i;
 *
 * In Halide layout, data(i,j) in C is mapped to data(j,i) in Buffer.
 */
static
void init_array(int m,
                int n,
                num_t *float_n,
                Halide::Buffer<num_t, 2> data)
{
    // float_n = (DATA_TYPE) n;
    *float_n = static_cast<num_t>(n);

    // Use Halide to fill the data buffer.
    Var i("i_init"), j("j_init");
    Func init_data("init_data");

    // C code: data[i][j] = (DATA_TYPE)(i*j)/M + i;
    // Here, i and j are ints; M is 'm'.
    // We must ensure the division is done in floating point, so we cast
    // both numerator and denominator to num_t.
    Expr ij     = i * j;
    Expr num    = cast<num_t>(ij);
    Expr denom  = cast<num_t>(Expr(m));
    Expr term_i = cast<num_t>(i);

    // Layout in Buffer: data(j, i) corresponds to C data[i][j].
    init_data(j, i) = num / denom + term_i;

    // A simple schedule: compute at root, vectorize across the
    // unit-stride j dimension, and parallelize across rows i.
    Target t = get_host_target();
    const int vec = t.natural_vector_size(type_of<num_t>());

    init_data
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    // Realize into the provided buffer (width = m, height = n).
    init_data.realize(data);
}


int main(int argc, char *argv[]) {
    // Problem size (from correlation.hpp / defines.hpp).
    int n = N; // number of rows (samples)
    int m = M; // number of columns (variables)

    // Scalar corresponding to float_n in the original C code.
    num_t float_n = static_cast<num_t>(n);

    // Buffers:
    //  - data: N x M in C as data[i][j]
    //    => Buffer width = M (j), height = N (i) => data(j, i)
    //  - corr: M x M in C as corr[i][j]
    //    => Buffer width = M (j), height = M (i) => corr(j, i)
    Halide::Buffer<num_t, 2> data(m, n);
    Halide::Buffer<num_t, 2> corr_buf(m, m);

    // Initialize the input data (and float_n).
    init_array(m, n, &float_n, data);

    // --- Build Halide correlation pipeline ---

    // ImageParam for the input data.
    // Layout: data_param(j, i) corresponds to C data[i][j].
    ImageParam data_param(type_of<num_t>(), 2, "data_param");

    // Scalar parameter for float_n.
    Param<num_t> float_n_param("float_n_param");

    // Vars: i = row index (0..n-1), j = column index (0..m-1)
    //       p,q = indices for correlation matrix (0..m-1)
    Var i("i"), j("j"), p("p"), q("q");

    // Column-wise mean: mean[j]
    //
    // Original C (PolyBench):
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
    //       mean[j] += data[i][j];
    //   mean[j] /= float_n;
    //
    // Our Halide version matches the original arithmetic order:
    //   mean[j] = sum_i (data[i][j] / float_n)
    Func mean("mean");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(Expr(0.0));

        mean(j) = zero;
        mean(j) += data_param(j, r_mean) / float_n_param;
    }

    // Column-wise variance accumulator (without dividing by float_n yet):
    //
    //   var[j] = sum_i (data[i][j] - mean[j])^2
    //
    // This mirrors the original "stddev" accumulation, but we keep
    // it as a separate Func to make the pipeline clearer.
    Func var("var");
    {
        RDom r_var(0, n, "r_var");
        Expr zero = cast<num_t>(Expr(0.0));

        var(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var(j) += diff * diff;
    }

    // Standard deviation with epsilon handling:
    //
    // Original C:
    //   stddev[j] = 0;
    //   for (i) stddev[j] += (data[i][j] - mean[j])^2;
    //   stddev[j] /= float_n;
    //   stddev[j] = sqrt(stddev[j]);
    //   stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    //
    // Our version:
    //   sigma[j]  = sqrt(var[j] / float_n);
    //   stddev[j] = (sigma[j] <= eps) ? 1.0 : sigma[j];
    Func stddev("stddev");
    {
        Expr eps = cast<num_t>(Expr(0.1));  // SCALAR_VAL(0.1)
        Expr one = cast<num_t>(Expr(1.0));
        Expr sigma = sqrt(var(j) / float_n_param);
        stddev(j) = select(sigma <= eps, one, sigma);
    }

    // Precompute a per-column scaling factor to fold normalization into
    // the correlation computation:
    //
    //   normalized[i][j] =
    //       (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
    //
    // so we define:
    //
    //   scale[j] = 1 / (sqrt(float_n) * stddev[j])
    //
    // and later use it as:
    //
    //   normalized[i][j] = (data[i][j] - mean[j]) * scale[j]
    //
    // This removes the division from the inner loops and eliminates the
    // need to materialize a full N×M normalized buffer.
    Func scale("scale");
    {
        Expr one    = cast<num_t>(Expr(1.0));
        Expr sqrt_n = sqrt(float_n_param);
        scale(j)    = one / (sqrt_n * stddev(j));
    }

    // Correlation base: unnormalized covariance-like term.
    //
    // Using normalized data:
    //   norm[i][j] = (data[i][j] - mean[j]) * scale[j]
    //
    // the correlation between columns p and q is:
    //   corr[p][q] = sum_k norm[k][p] * norm[k][q]
    //              = scale[p] * scale[q] *
    //                sum_k (data[k][p] - mean[p]) * (data[k][q] - mean[q])
    //
    // We compute the inner sum as corr_base[q,p] (note the (q,p) layout
    // so that q is the innermost, unit-stride dimension):
    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(Expr(0.0));

        corr_base(q, p) = zero;
        Expr dp = data_param(q, r_k) - mean(q);
        Expr dq = data_param(p, r_k) - mean(p);
        corr_base(q, p) += dp * dq;
    }

    // Final correlation matrix:
    //
    //   corr[p][q] = 1                     if p == q
    //   corr[p][q] = scale[p]*scale[q] *
    //                corr_base[q][p]       otherwise
    //
    // We explicitly set the diagonal to 1.0 to exactly match the original
    // C behavior (which sets corr[i][i] = 1.0 and never touches it again).
    Func corr("corr");
    {
        Expr one = cast<num_t>(Expr(1.0));
        corr(q, p) = select(p == q,
                            one,
                            corr_base(q, p) * scale(q) * scale(p));
    }

    // --- Scheduling: focus on data locality and parallelism ---

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    // Reasonable tile size for 1D column-wise passes.
    const int tile_j = 64;
    // Reasonable row tile for correlation (rows of corr / columns of variables).
    const int tile_p = 32;

    // 1) Column-wise statistics: mean, var, stddev, scale.
    //
    // Each statistic is independent across j (the column index), so we
    // parallelize across tiles of j and vectorize within each tile.
    {
        Var jo("jo"), ji("ji");

        mean.compute_root()
            .split(j, jo, ji, tile_j)
            .parallel(jo)
            .vectorize(ji, vec_width);

        mean.update()
            .split(j, jo, ji, tile_j)
            .parallel(jo)
            .vectorize(ji, vec_width);
    }

    {
        Var jo("var_jo"), ji("var_ji");

        var.compute_root()
           .split(j, jo, ji, tile_j)
           .parallel(jo)
           .vectorize(ji, vec_width);

        var.update()
           .split(j, jo, ji, tile_j)
           .parallel(jo)
           .vectorize(ji, vec_width);
    }

    {
        Var jo("stddev_jo"), ji("stddev_ji");

        stddev.compute_root()
              .split(j, jo, ji, tile_j)
              .parallel(jo)
              .vectorize(ji, vec_width);
    }

    {
        Var jo("scale_jo"), ji("scale_ji");

        scale.compute_root()
             .split(j, jo, ji, tile_j)
             .parallel(jo)
             .vectorize(ji, vec_width);
    }

    // 2) Correlation base (the heavy reduction over samples).
    //
    // corr_base(q, p) has:
    //   - p: correlation "row"/variable index  (outer)
    //   - q: correlation "column"/variable index (inner, unit-stride)
    //
    // We:
    //   - compute corr_base at root,
    //   - parallelize across p in tiles,
    //   - vectorize across q (contiguous dimension).
    {
        Var po("po"), pi("pi");

        corr_base.compute_root();

        // Pure definition: zero-initialize corr_base.
        corr_base
            .split(p, po, pi, tile_p)
            .parallel(po)
            .vectorize(q, vec_width);

        // Update (reduction) definition: same tiling/parallelism.
        corr_base.update()
                 .split(p, po, pi, tile_p)
                 .parallel(po)
                 .vectorize(q, vec_width);
    }

    // 3) Final corr:
    //
    // corr(q, p) is a pure Func (no reductions). We parallelize across
    // rows p in tiles and vectorize across q (unit-stride).
    {
        Var po("corr_po"), pi("corr_pi");

        corr.compute_root()
            .split(p, po, pi, tile_p)
            .parallel(po)
            .vectorize(q, vec_width);
    }

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline for the host.
    pipeline.compile_jit(target);

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
