    // Problem size (from correlation.hpp / defines.hpp).
    int n = N; // number of rows (samples)
    int m = M; // number of columns (variables)

    // Scalar corresponding to float_n in the original C code.
    num_t float_n = static_cast<num_t>(n);

    // Buffers:
    //  - data: N x M in C as data[i][j]
    //    => Buffer width = M (j), height = N (i) => data(j, i)
    //  - corr: M x M in C as corr[i][j]
    //    => Buffer width = M (j), height = M (i) => corr(j, i)
    Halide::Buffer<num_t, 2> data(m, n);
    Halide::Buffer<num_t, 2> corr_buf(m, m);

    // Initialize the input data (and float_n, though we also set float_n directly).
    init_array(m, n, &float_n, data);

    // --- Build Halide correlation pipeline ---

    // ImageParam for the input data.
    // Layout: data_param(j, i) corresponds to C data[i][j].
    ImageParam data_param(type_of<num_t>(), 2, "data_param");

    // Scalar parameter for float_n.
    Param<num_t> float_n_param("float_n_param");

    // Vars:
    //   i = row index (0..n-1)   -> samples
    //   j = column index (0..m-1)-> variables
    //   p,q = indices for correlation matrix (0..m-1)
    Var i("i"), j("j"), p("p"), q("q");

    // Column-wise statistics and scaling:
    Func mean("mean");         // mean[j]
    Func var("var");           // sum of squared deviations
    Func stddev("stddev");     // standard deviation with epsilon guard
    Func inv_scale("inv_scale"); // 1 / (sqrt(float_n) * stddev[j])

    // Reduction domains for statistics and correlation.
    RDom r_mean(0, n, "r_mean");
    RDom r_var(0, n, "r_var");
    RDom r_corr(0, n, "r_corr");

    // ------------------------------------------------------------------------
    // 1) Column-wise mean:
    //    mean[j] = (1 / float_n) * sum_i data[i][j]
    //    Implemented as incremental average to stay very close to original C.
    // ------------------------------------------------------------------------
    {
        Expr zero = cast<num_t>(0);
        mean(j) = zero;
        mean(j) += data_param(j, r_mean) / float_n_param;
    }

    // ------------------------------------------------------------------------
    // 2) Column-wise variance accumulator:
    //    var[j] = sum_i (data[i][j] - mean[j])^2
    // ------------------------------------------------------------------------
    {
        Expr zero = cast<num_t>(0);
        var(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var(j) += diff * diff;
    }

    // ------------------------------------------------------------------------
    // 3) Standard deviation and per-column inverse scaling:
    //
    // Original C:
    //   stddev[j] = 0;
    //   for (i) stddev[j] += (data[i][j] - mean[j])^2;
    //   stddev[j] /= float_n;
    //   stddev[j] = sqrt(stddev[j]);
    //   stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    //
    // We already have:
    //   var[j] = sum_i (data[i][j] - mean[j])^2
    //
    // So we compute:
    //   sigma = sqrt(var[j] / float_n);
    //   stddev[j] = (sigma <= eps) ? 1.0 : sigma;
    //
    // Then precompute:
    //   inv_scale[j] = 1 / (sqrt(float_n) * stddev[j])
    //
    // so that normalized values in the correlation stage are:
    //   norm(i,j) = (data[i][j] - mean[j]) * inv_scale[j]
    // ------------------------------------------------------------------------
    {
        Expr eps = cast<num_t>(Expr(0.1));   // SCALAR_VAL(0.1)
        Expr one = cast<num_t>(Expr(1.0));
        Expr sigma = sqrt(var(j) / float_n_param);
        stddev(j) = select(sigma <= eps, one, sigma);

        Expr sqrt_n = sqrt(float_n_param);
        inv_scale(j) = one / (sqrt_n * stddev(j));
    }

    // ------------------------------------------------------------------------
    // 4) Correlation matrix.
    //
    // Using the conceptual normalized data:
    //   norm(i,j) = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
    //             = (data[i][j] - mean[j]) * inv_scale[j]
    //
    // The correlation between columns p and q is:
    //   corr[p][q] = sum_k norm(k,p) * norm(k,q)
    //
    // The original C sets diag to 1.0 explicitly, and copies corr[i][j]
    // to corr[j][i]. Here we compute the full symmetric matrix directly:
    //
    //   If p == q: corr[p][p] = 1.0
    //   If p != q: corr[p][q] = sum_k norm(k,p) * norm(k,q)
    //
    // We express it as a single reduction Func with a guarded update:
    //   corr(q,p) initialized to 1.0 on the diagonal and 0 elsewhere,
    //   then we add the dot-products only for off-diagonal entries.
    // ------------------------------------------------------------------------
    Func corr("corr");
    {
        Expr one  = cast<num_t>(Expr(1.0));
        Expr zero = cast<num_t>(0);

        // Pure definition: initialize diagonal to 1, off-diagonal to 0.
        // corr_buf(q, p) corresponds to C corr[p][q].
        corr(q, p) = select(p == q, one, zero);

        // Update definition: add contributions from the normalized dot product
        // only for off-diagonal entries. Diagonal entries remain exactly 1.0.
        Expr norm_p = (data_param(p, r_corr) - mean(p)) * inv_scale(p);
        Expr norm_q = (data_param(q, r_corr) - mean(q)) * inv_scale(q);
        corr(q, p) += select(p == q, cast<num_t>(0), norm_p * norm_q);
    }

    // --------------------- Scheduling for performance ----------------------

    // Get host target so we can choose a reasonable vector width.
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;
    }

    // 1) Column statistics (mean and var):
    //
    // Access pattern:
    //   data_param(j, i) is laid out row-major in j (C data[i][j]).
    //   To exploit contiguous memory, we want the inner loop over j.
    //
    // We reorder the reduction update to:
    //   for r_mean (i = sample):
    //     for j (variables, contiguous):
    //       mean[j] += data_param(j, r_mean) / float_n;
    //
    // and vectorize across j. This gives good cache and SIMD behavior.
    mean.compute_root();
    mean.update()
        .reorder(j, r_mean);          // r_mean outer, j innermost
    if (vec_width > 1) {
        mean.update().vectorize(j, vec_width);
    }

    var.compute_root();
    var.update()
        .reorder(j, r_var);           // r_var outer, j innermost
    if (vec_width > 1) {
        var.update().vectorize(j, vec_width);
    }

    // 2) stddev and inv_scale: simple 1D computations over j.
    //    Compute at root and SIMD-vectorize along j.
    stddev.compute_root();
    inv_scale.compute_root();
    if (vec_width > 1) {
        stddev.vectorize(j, vec_width);
        inv_scale.vectorize(j, vec_width);
    }

    // 3) Correlation matrix:
    //
    // Heavy O(M^2 * N) kernel. We:
    //   * tile (p,q) so that corr tiles fit in cache,
    //   * parallelize over tiles in p,
    //   * vectorize across q (unit-stride dimension in corr and data),
    //   * keep the reduction RVar r_corr innermost within each tile.
    //
    Var q_outer("q_outer"), q_inner("q_inner");
    Var p_outer("p_outer"), p_inner("p_inner");

    const int tile_q = 32;  // tile size along q (columns of corr)
    const int tile_p = 32;  // tile size along p (rows of corr)

    // Schedule for the pure definition (initialization of corr):
    corr
        .compute_root()
        .tile(q, p, q_outer, p_outer, q_inner, p_inner, tile_q, tile_p)
        // Inner loops: q_inner (fastest, contiguous), then p_inner.
        .reorder(q_inner, p_inner, q_outer, p_outer)
        .parallel(p_outer);
    if (vec_width > 1) {
        corr.vectorize(q_inner, vec_width);
    }

    // Schedule for the reduction update (accumulating dot products).
    corr.update()
        .tile(q, p, q_outer, p_outer, q_inner, p_inner, tile_q, tile_p)
        // Loop order: outer tiles in p,q; then reduction r_corr;
        // then inner p,q with q_inner innermost for contiguous accesses.
        .reorder(q_inner, p_inner, r_corr, q_outer, p_outer)
        .parallel(p_outer);
    if (vec_width > 1) {
        corr.update().vectorize(q_inner, vec_width);
    }

    // ----------------------------------------------------------------------

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline with the chosen target.
    pipeline.compile_jit(target);

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
