    // Scalar parameter for float_n.
    Param<num_t> float_n_param("float_n_param");

    // Vars: i = row index (0..n-1), j = column index (0..m-1)
    //       p,q = indices for correlation matrix (0..m-1)
    Var i("i"), j("j"), p("p"), q("q");

    // ------------------------------------------
    // Column-wise statistics:
    //
    // 1) mean[j]  = sum_i data[i][j] / float_n
    // 2) var[j]   = sum_i (data[i][j] - mean[j])^2
    // 3) stddev[j] and scale[j] = 1 / (sqrt(float_n)*stddev[j])
    //
    // These are all 1D in j and inexpensive compared to the O(M^2 N)
    // correlation phase, but we still compute them once at root.
    // ------------------------------------------

    // Column-wise mean: mean[j] = sum_i data[i][j] / float_n.
    Func mean("mean");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(0.0);

        // Accumulate the sum, then divide by float_n outside the reduction.
        Func mean_sum("mean_sum");
        mean_sum(j) = zero;
        mean_sum(j) += data_param(j, r_mean);

        mean(j) = mean_sum(j) / float_n_param;
    }

    // Column-wise variance accumulator (unnormalized):
    //   var[j] = sum_i (data[i][j] - mean[j])^2
    Func var("var");
    {
        RDom r_var(0, n, "r_var");
        Expr zero = cast<num_t>(0.0);

        var(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var(j) += diff * diff;
    }

