        Expr eps    = cast<num_t>(0.1);   // SCALAR_VAL(0.1)
        Expr one    = cast<num_t>(1.0);
        Expr sqrt_n = sqrt(float_n_param);

        Expr sigma = sqrt(var(j) / float_n_param);
        Expr sigma_checked = select(sigma <= eps, one, sigma);
        stddev(j) = sigma_checked;

        scale(j) = one / (sqrt_n * stddev(j));
    }

