    // Correlation matrix:
    //
    // Conceptually, the normalized data is:
    //   normalized[i][j] =
    //     (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
    //
    // We avoid materializing a full N×M normalized array; instead we
    // fold the normalization into the correlation dot product:
    //
    //   norm(i,j) = (data[i][j] - mean[j]) * scale[j]
    //
    // Then
    //   corr[p][q] = sum_k norm(k,p) * norm(k,q)
    //
    // We implement this as a reduction over k (0..n-1) for every (p,q),
    // and then explicitly set the diagonal to 1.0 to match the original
    // PolyBench semantics.
    // ------------------------------------------

    RDom r_k(0, n, "r_k");

    // Unnormalized correlation (dot products of normalized columns).
    Func corr_base("corr_base");
    {
        Expr zero = cast<num_t>(0.0);

        corr_base(q, p) = zero;

        // dp = normalized sample for column p at row r_k
        Expr dp = (data_param(p, r_k) - mean(p)) * scale(p);
        // dq = normalized sample for column q at row r_k
        Expr dq = (data_param(q, r_k) - mean(q)) * scale(q);

        corr_base(q, p) += dp * dq;
    }

    // Final correlation with diagonal forced to 1.0.
    Func corr("corr");
    {
        Expr one = cast<num_t>(1.0);
        corr(q, p) = select(p == q, one, corr_base(q, p));
