        Func mean_sum = Func(mean.function().get_contents().definition().values()[0].as<Call>()->func);
        // mean_sum is internal, but we don't strictly need to schedule it
        // explicitly; the default (compute_root) is fine. Leaving it as-is
        // keeps the code simple and portable across Halide versions.
        (void)mean_sum;
    }

    // Parallelize the reductions over columns for mean/var by their update steps.
    {
        // mean has a single update step (the reduction).
        mean.update().parallel(j);
        var.update().parallel(j);
        // stddev and scale are pure 1D Funcs over j; parallelize them as well.
        stddev.parallel(j);
        scale.parallel(j);
    }

    // Correlation is the hot kernel. We tile in p, q, and k, and
    // parallelize across tiles in p; within a tile we vectorize in q.
    {
        Var qo("qo"), po("po"), qi("qi"), pi("pi");
        RVar rko("rko"), rki("rki");

        const int tile_q = 32;  // tile size along q (columns of corr)
        const int tile_p = 32;  // tile size along p (rows of corr)
        const int tile_k = 64;  // tile size along reduction dim k (samples)

        // Pure definition: lay out corr_base tiles and parallelize over tile rows.
        corr_base
            .compute_root()
            .tile(q, p, qo, po, qi, pi, tile_q, tile_p)
            .parallel(po)
            .vectorize(qi, vec_width);

        // Reduction update: do a 3D tiling over (q,p,k).
        corr_base.update()
            .tile(q, p, qo, po, qi, pi, tile_q, tile_p)
            .split(r_k, rko, rki, tile_k)
            // Reorder so that within each (qo,po,rko) tile, we iterate
