    // Vars:
    //   i = row index (0..n-1), j = column index (0..m-1)
    //   p,q = indices for correlation matrix (0..m-1)
    Var i("i"), j("j"), p("p"), q("q");

    // ---------------------------------------------
    // 1. Column-wise mean:
    //
    // Original C:
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
    //       mean[j] += data[i][j];
    //   mean[j] /= float_n;
    //
    // Our original Halide code followed the PolyBench variant:
    //   mean[j] += data[i][j] / float_n;
    //
    // To preserve the same arithmetic ordering, we keep that form:
    //   mean(j) = sum_i data(i,j) / float_n_param
    // implemented as a reduction update.
    // ---------------------------------------------
    Func mean("mean");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(Expr(0.0));

        mean(j) = zero;
        mean(j) += data_param(j, r_mean) / float_n_param;
    }

    // ---------------------------------------------
    // 2. Column-wise variance accumulator (no division by float_n yet):
    //
    //   var[j] = sum_i (data[i][j] - mean[j])^2
    //
    // We keep this as a separate reduction Func.
    // ---------------------------------------------
    Func var("var");
    {
        RDom r_var(0, n, "r_var");
        Expr zero = cast<num_t>(Expr(0.0));

        var(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var(j) += diff * diff;
    }

    // ---------------------------------------------
    // 3. Standard deviation with epsilon handling:
    //
    // Original C:
    //   stddev[j] = 0;
    //   for (i) stddev[j] += (data[i][j] - mean[j])^2;
    //   stddev[j] /= float_n;
    //   stddev[j] = sqrt(stddev[j]);
    //   stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    //
    // In terms of var[j] above:
    //   sigma = sqrt(var[j] / float_n);
    //   stddev[j] = (sigma <= eps) ? 1.0 : sigma;
    // ---------------------------------------------
    Func stddev("stddev");
    {
        Expr eps = cast<num_t>(Expr(0.1));  // SCALAR_VAL(0.1)
        Expr one = cast<num_t>(Expr(1.0));
        Expr sigma = sqrt(var(j) / float_n_param);
        stddev(j) = select(sigma <= eps, one, sigma);
    }

    // ---------------------------------------------
    // 4. Precompute per-column scaling factor:
    //
    //   scale[j] = 1 / (sqrt(float_n) * stddev[j])
    //
    // This lets us avoid materializing a full normalized N×M buffer.
    // ---------------------------------------------
    Func scale("scale");
    {
        Expr one = cast<num_t>(Expr(1.0));
        Expr sqrt_n = sqrt(float_n_param);
        scale(j) = one / (sqrt_n * stddev(j));
    }

    // ---------------------------------------------
    // 5. Correlation matrix via dot products of normalized columns.
    //
    // Conceptually, normalized data is:
    //   normalized(i,j) = (data[i][j] - mean[j]) / (sqrt(float_n)*stddev[j])
    //                   = (data[i][j] - mean[j]) * scale[j]
    //
    // The off-diagonal entries are:
    //   corr[p][q] = sum_k normalized[k][p] * normalized[k][q]
    //
    // We do not store normalized[i][j]; we apply the normalization
    // on the fly inside the reduction to keep memory usage low and
    // improve data locality.
    //
    // As in the original C, we explicitly set the diagonal to 1.0.
    // ---------------------------------------------
    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(Expr(0.0));

        // corr_base(q,p) ≈ sum_k normalized(k,q) * normalized(k,p)
        corr_base(q, p) = zero;

        Expr norm_q = (data_param(q, r_k) - mean(q)) * scale(q);
        Expr norm_p = (data_param(p, r_k) - mean(p)) * scale(p);
        corr_base(q, p) += norm_q * norm_p;
    }

    Func corr("corr");
    {
        Expr one = cast<num_t>(Expr(1.0));
        // corr_buf(q, p) corresponds to C corr[p][q].
        // Force diagonal to 1.0 to match the reference semantics.
        corr(q, p) = select(p == q, one, corr_base(q, p));
    }

    // ------------------------------------------------------------------
    // Scheduling:
    //
    //  - mean / var / stddev / scale are 1D in j, independent across
    //    columns, so we compute them at root and parallelize in j.
    //
    //  - corr_base is the hot O(M^2 * N) kernel. We:
    //      * compute it at root into an M×M buffer,
    //      * tile (q,p) into 2D tiles for cache locality,
    //      * parallelize across tiles,
    //      * vectorize across q, the innermost, unit-stride dimension.
    //
    //  - corr is a light post-processing stage; we parallelize and
    //    vectorize it as well.
    //
    //  The schedule is conservative (no splitting of the reduction
    //  variable r_k), so there are no dangers of double-counting
    //  reduction terms.
    // ------------------------------------------------------------------

    // Choose a conservative vector width and tile sizes for x64.
    const int vec_width   = 8;   // reasonable default (SSE/AVX-friendly)
    const int tile_q_size = 32;  // tile size along q (columns)
    const int tile_p_size = 32;  // tile size along p (rows)

    // Statistics: mean, var, stddev, scale.
    {
        Var jo("jo"), ji("ji");

        mean.compute_root();
        mean.split(j, jo, ji, 64)
            .parallel(jo)
            .vectorize(ji, vec_width);
        mean.update()
            .split(j, jo, ji, 64)
            .parallel(jo)
            .vectorize(ji, vec_width);

        var.compute_root();
        var.split(j, jo, ji, 64)
           .parallel(jo)
           .vectorize(ji, vec_width);
        var.update()
           .split(j, jo, ji, 64)
           .parallel(jo)
           .vectorize(ji, vec_width);

        stddev.compute_root()
              .split(j, jo, ji, 64)
              .parallel(jo)
              .vectorize(ji, vec_width);

        scale.compute_root()
             .split(j, jo, ji, 64)
             .parallel(jo)
             .vectorize(ji, vec_width);
    }

    // Correlation base: heavy reduction over samples.
    {
        Var qo("qo"), qi("qi"), po("po"), pi("pi"), tile_index("tile_index");
        RVar r_k("r_k");

        // Pure definition: tiling and parallelization across tiles.
        corr_base.compute_root()
                 .tile(q, p, qo, po, qi, pi,
                       tile_q_size, tile_p_size)
                 .fuse(qo, po, tile_index)
                 .parallel(tile_index)
                 .vectorize(qi, vec_width);

        // Update definition (reduction): mirror the same tiling/loop
        // structure so that accumulation happens tile-by-tile. We
        // keep r_k innermost after qi/pi to get good locality in the
        // sample (row) dimension and vectorize across qi.
        corr_base.update()
                 .tile(q, p, qo, po, qi, pi,
                       tile_q_size, tile_p_size)
                 .fuse(qo, po, tile_index)
                 .reorder(qi, pi, r_k, tile_index)
                 .parallel(tile_index)
                 .vectorize(qi, vec_width);
    }

    // Final corr: light post-processing, parallel over rows and
    // vectorize across columns.
    {
        Var po("po"), pi("pi");
        corr.compute_root()
            .split(p, po, pi, 32)
            .parallel(po)
            .vectorize(q, vec_width);
    }

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline.
    pipeline.compile_jit();

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
